import{_ as e,o as t,c as r,a2 as i}from"./chunks/framework.CHeM0PsO.js";const l="/images/agent-square.webp",g=JSON.parse('{"title":"游玩入门","description":"","frontmatter":{},"headers":[],"relativePath":"guide/agent/quick-start.md","filePath":"guide/agent/quick-start.md","lastUpdated":1789295632000}'),o={name:"guide/agent/quick-start.md"};function n(s,a,d,h,p,u){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="游玩入门" tabindex="-1">游玩入门 <a class="header-anchor" href="#游玩入门" aria-label="Permalink to &quot;游玩入门&quot;">​</a></h1><p>智能体是本站的核心功能：和有性格、有记忆的 AI 角色聊天。你可以直接玩别人发布的角色，也可以<a href="/guide/agent/create">创作自己的角色</a>。</p><h2 id="开始之前-先有一份对话风格" tabindex="-1">开始之前：先有一份对话风格 <a class="header-anchor" href="#开始之前-先有一份对话风格" aria-label="Permalink to &quot;开始之前：先有一份对话风格&quot;">​</a></h2><p>对话风格决定角色「怎么说话」（语气、人称、句长、是否有动作描写）。社区游玩前，你需要至少拥有一份可用的风格——自己<a href="/guide/agent/styles">创建</a>一份，或去风格广场把别人公开的风格「加入我的列表」。</p><p>第一次进入会话时如果没有可用风格，页面会引导你去风格广场挑选。</p><h2 id="从广场找角色" tabindex="-1">从广场找角色 <a class="header-anchor" href="#从广场找角色" aria-label="Permalink to &quot;从广场找角色&quot;">​</a></h2><p>进入「智能体 → 广场」，可以：</p><ul><li>按<strong>推荐、热度、评分、最新</strong>排序浏览所有已发布角色。</li><li>用搜索框按<strong>名称、简介、作者</strong>找角色（多个关键词用空格分隔）。</li><li>查看角色卡片：头像、名称、简介、创作者、评分、会话次数、对话次数等。</li></ul><p><img src="'+l+'" alt="智能体广场"></p><p>点击角色进入详情页，可以看到「提示词规模」（角色卡各部分的字数统计）、评分分布和<a href="#参与评价">评价列表</a>，确认感兴趣再开始聊天。</p><h2 id="开始聊天" tabindex="-1">开始聊天 <a class="header-anchor" href="#开始聊天" aria-label="Permalink to &quot;开始聊天&quot;">​</a></h2><ol><li>在角色详情页点击「开始聊天」，确认后创建新会话。</li><li>选择一个<strong>对话风格</strong>（第一次会被引导先去添加）。</li><li>发送第一条消息。如果角色写了开场白，会话创建时会自动出现。</li></ol><p>旧的会话不会丢：在「私信」页面的「智能体」标签页可以找到所有历史会话，点击即可继续对话。详见<a href="/guide/agent/chat">聊天与会话</a>。</p><p>同一个角色可以开多个会话，比如走不同的剧情线。</p><h2 id="参与评价" tabindex="-1">参与评价 <a class="header-anchor" href="#参与评价" aria-label="Permalink to &quot;参与评价&quot;">​</a></h2><p>在广场的角色详情页可以打分（0～5 星）并写评价。注意：</p><ul><li>评价会以 Misskey 帖文的形式发布，可见范围和普通帖子一致。</li><li>创作者看到高质量评价也是继续更新的动力。</li></ul><h2 id="草稿测试与社区游玩" tabindex="-1">草稿测试与社区游玩 <a class="header-anchor" href="#草稿测试与社区游玩" aria-label="Permalink to &quot;草稿测试与社区游玩&quot;">​</a></h2><p>会话分两种：</p><ul><li><strong>草稿测试</strong>：你自己在「创作」页测试角色草稿时产生的会话，只有你能看到。</li><li><strong>社区游玩</strong>：和已发布的角色聊天产生的会话。</li></ul><p>两者功能一致，删除会话时都会连带删除记忆数据，详见<a href="/guide/agent/memory">记忆</a>。</p>',21)])])}const _=e(o,[["render",n]]);export{g as __pageData,_ as default};
